import React, { useEffect, useRef, useState, useCallback } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader';

const GlbTest = () => {
  const canvasRef = useRef(null);
  const rendererRef = useRef(null);
  const sceneRef = useRef(null);
  const cameraRef = useRef(null);
  const clockRef = useRef(new THREE.Clock());
  const [isPlaying, setIsPlaying] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState('Loading...');
  const [error, setError] = useState(null);
  const [loadedModels, setLoadedModels] = useState([]);
  const modelsRef = useRef([]);

  const loadModel = useCallback((modelPath, onLoad) => {
    const loader = new GLTFLoader();

    loader.load(
      modelPath, 
      (gltf) => {
        const model = gltf.scene;
        sceneRef.current.add(model);

        const mixer = new THREE.AnimationMixer(model);
        let action = null;

        if (gltf.animations.length > 0) {
          action = mixer.clipAction(gltf.animations[0]);
          action.setLoop(THREE.LoopRepeat);
          action.clampWhenFinished = true;

          // Ensure the animation state is synchronized with isPlaying
          if (isPlaying) {
            action.play();
          }
        }

        const newModel = { model, mixer, action };
        modelsRef.current.push(newModel);

        // 검증용 콘솔 출력
        console.log('Loaded model:', newModel);
        console.log('All models:', modelsRef.current);

        // Adjust camera to fit all models
        updateCameraView();

        if (onLoad) onLoad();
      },
      (xhr) => {
        if (xhr.lengthComputable) {
          const percentComplete = xhr.loaded / xhr.total * 100;
          setLoadingStatus(`${Math.round(percentComplete)}% loaded`);
        }
      },
      (error) => {
        console.error('Error loading GLB file:', error);
        setError(`Failed to load model: ${error.message}`);
        setLoadingStatus('Load Failed');
      }
    );
  }, [isPlaying]);


  const updateCameraView = useCallback(() => {
    if (modelsRef.current.length === 0) return;

    const box = new THREE.Box3();
    modelsRef.current.forEach(({ model }) => {
      box.expandByObject(model);
    });

    const center = box.getCenter(new THREE.Vector3());
    const size = box.getSize(new THREE.Vector3());

    const maxDim = Math.max(size.x, size.y, size.z);
    const fov = cameraRef.current.fov * (Math.PI / 180);
    let cameraZ = Math.abs(maxDim / 2 / Math.tan(fov / 2));
    cameraZ *= 1.5;

    cameraRef.current.position.set(center.x, center.y, center.z + cameraZ);
    cameraRef.current.lookAt(center);
    cameraRef.current.updateProjectionMatrix();
  }, []);
  useEffect(() => {
    // 이 부분에서 loadModel 함수가 의도치 않게 여러 번 호출되지 않도록 확인
    loadModel('/static/models/body__animated_test.glb', () => setLoadingStatus('Loaded Successfully'));

    const animate = () => {
      requestAnimationFrame(animate);

      const delta = clockRef.current.getDelta();
      modelsRef.current.forEach(({ mixer }) => mixer.update(delta));

      if (rendererRef.current && sceneRef.current && cameraRef.current) {
        rendererRef.current.render(sceneRef.current, cameraRef.current);
      }
    };

    animate();

    return () => {
      if (rendererRef.current) {
        rendererRef.current.dispose();
      }
    };
  }, [loadModel]);


  const toggleAnimation = () => {
    const newIsPlaying = !isPlaying;
    setIsPlaying(newIsPlaying);
    modelsRef.current.forEach(({ action }) => {
      if (action) {
        if (newIsPlaying) {
          if (action.paused) {
            action.paused = false;
          } else {
            action.play();
          }
        } else {
          action.paused = true;
        }
      }
    });
  };


  const loadAdditionalModel = (modelPath) => {
    if (!loadedModels.includes(modelPath)) {
      loadModel(modelPath, () => {
        setLoadedModels(prevLoadedModels => [...prevLoadedModels, modelPath]);
        setLoadingStatus(`Model ${modelPath} Loaded`);
        updateCameraView();
      });
    }
  };

  return (
    <div>
      <canvas ref={canvasRef} style={{ width: '400px', height: '400px', border: '1px solid black' }} />
      <div style={{ marginTop: '10px' }}>
        <p>Status: {loadingStatus}</p>
        {error && <p style={{ color: 'red' }}>{error}</p>}
      </div>
      <button 
        onClick={toggleAnimation}
        disabled={loadingStatus !== 'Loaded Successfully' && loadedModels.length === 0}
        style={{
          marginTop: '10px',
          padding: '5px 10px',
          fontSize: '14px',
          marginRight: '10px'
        }}
      >
        {isPlaying ? 'Pause Animations' : 'Start Animations'}
      </button>
      <button 
        onClick={() => loadAdditionalModel('/static/models/body__animated_test_top.glb')}
        disabled={loadedModels.includes('/static/models/body__animated_test_top.glb')}
        style={{
          marginTop: '10px',
          padding: '5px 10px',
          fontSize: '14px',
          marginRight: '10px'
        }}
      >
        Load Model 1
      </button>
      <button 
        onClick={() => loadAdditionalModel('/static/models/body__animated_test_bottom.glb')}
        disabled={loadedModels.includes('/static/models/body__animated_test_bottom.glb')}
        style={{
          marginTop: '10px',
          padding: '5px 10px',
          fontSize: '14px',
          marginRight: '10px'
        }}
      >
        Load Model 2
      </button>
      <button 
        onClick={() => loadAdditionalModel('/static/models/body__animated_test_accessory.glb')}
        disabled={loadedModels.includes('/static/models/body__animated_test_accessory.glb')}
        style={{
          marginTop: '10px',
          padding: '5px 10px',
          fontSize: '14px'
        }}
      >
        Load Model 3
      </button>
    </div>
  );
};

export default GlbTest;
